-- ---------------------------------------------------------------------------------------------
-- Integrity checks that hold whatever code writes (data-model §5.5 step 4).
ALTER TABLE "businesses"
  ADD CONSTRAINT businesses_slug_format CHECK ("slug" ~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'),
  ADD CONSTRAINT businesses_country_format CHECK ("country_code" ~ '^[A-Z]{2}$'),
  ADD CONSTRAINT businesses_currency_format CHECK ("currency" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT businesses_locale_format CHECK ("locale" ~ '^[a-z]{2,3}(-[A-Z][a-z]{3})?(-([A-Z]{2}|[0-9]{3}))?$'),
  ADD CONSTRAINT businesses_name_length CHECK (char_length("name") BETWEEN 1 AND 200);
ALTER TABLE "invitations"
  ADD CONSTRAINT invitations_token_hash_format CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT invitations_email_lower CHECK ("email" = lower("email"));
-- Ownership is never handed out by invitation; an owner promotes an existing member instead.
ALTER TABLE "invitations" ADD CONSTRAINT invitations_role_not_owner CHECK ("role" <> 'OWNER');

-- ---------------------------------------------------------------------------------------------
-- Least privilege for tenant code (data-model §5.1). bos_owner's default privileges would give
-- bos_app full rights; start from nothing and grant exactly what the tenancy services use.
REVOKE ALL ON "businesses", "memberships", "invitations", "audit_events" FROM bos_app;
GRANT SELECT ON "businesses" TO bos_app;
GRANT UPDATE ("name", "legal_name", "updated_at") ON "businesses" TO bos_app;
GRANT SELECT, DELETE ON "memberships" TO bos_app;
GRANT UPDATE ("role", "status", "updated_at") ON "memberships" TO bos_app;
GRANT SELECT, INSERT ON "invitations" TO bos_app;
GRANT UPDATE ("revoked_at") ON "invitations" TO bos_app;
GRANT SELECT, INSERT ON "audit_events" TO bos_app;
-- No INSERT on businesses or memberships: creating a business and accepting an invitation go
-- through the pre-tenant functions only. No UPDATE/DELETE on audit_events for anyone: append-only.

-- Tenant policy template (§5.2): FORCE so the table owner is subject to it too.
ALTER TABLE "businesses" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "businesses" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "businesses" FOR ALL TO bos_app
  USING      ("id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "memberships" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "memberships" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "memberships" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

ALTER TABLE "invitations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "invitations" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "invitations" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);

-- Audit events (§5.6): tenant code reads and writes only its business's events; platform events
-- (business_id IS NULL) are invisible to it. bos_auth may write platform events only.
ALTER TABLE "audit_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "audit_events" FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_tenant_read ON "audit_events" FOR SELECT TO bos_app
  USING ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY audit_tenant_write ON "audit_events" FOR INSERT TO bos_app
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid
              AND "actor_user_id" = nullif(current_setting('app.user_id', true), '')::uuid);
GRANT INSERT ON "audit_events" TO bos_auth;
CREATE POLICY audit_platform_write ON "audit_events" FOR INSERT TO bos_auth
  WITH CHECK ("business_id" IS NULL);

-- Users visible to tenant code: the current user and members of the current business (§5.6).
DROP POLICY users_visible_to_app ON "users";
CREATE POLICY users_visible_to_app ON "users" FOR SELECT TO bos_app
  USING ("id" = nullif(current_setting('app.user_id', true), '')::uuid
         OR "id" IN (SELECT m."user_id" FROM "memberships" m));

-- ---------------------------------------------------------------------------------------------
-- Membership invariants enforced in the database as well as in modules/tenancy.

-- Nobody changes their own role (no self-escalation or self-demotion through the API).
CREATE FUNCTION public.memberships_no_self_role_change() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role
     AND OLD.user_id = nullif(current_setting('app.user_id', true), '')::uuid THEN
    RAISE EXCEPTION 'membership role change not allowed' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER memberships_no_self_role_change BEFORE UPDATE ON "memberships"
  FOR EACH ROW EXECUTE FUNCTION public.memberships_no_self_role_change();

-- Every active business keeps at least one active OWNER (checked at commit).
CREATE FUNCTION public.memberships_keep_an_owner() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF OLD.role = 'OWNER' AND OLD.status = 'ACTIVE'
     AND EXISTS (SELECT 1 FROM public.businesses b WHERE b.id = OLD.business_id AND b.archived_at IS NULL)
     AND NOT EXISTS (SELECT 1 FROM public.memberships m
                     WHERE m.business_id = OLD.business_id AND m.role = 'OWNER' AND m.status = 'ACTIVE') THEN
    RAISE EXCEPTION 'a business must keep at least one owner' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER memberships_keep_an_owner AFTER UPDATE OR DELETE ON "memberships"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.memberships_keep_an_owner();
